// V2 · Gestor de archivos
const FILE_HOME="/home/jorge",PROJECT_HOME="/srv/proyectos",FILE_ROOTS=[FILE_HOME,PROJECT_HOME],FILE_TRASH=path.join(FILE_HOME,".jr-server-trash");
const FILE_BLOCKED=["/root","/etc","/boot","/proc","/sys","/dev","/run","/var/lib","/usr","/bin","/sbin","/lib","/lib64"];
function filePath(input=""){const raw=String(input||"").trim();const p=path.resolve(raw.startsWith("/")?raw:path.join(FILE_HOME,raw));if(!FILE_ROOTS.some(root=>p===root||p.startsWith(root+path.sep)))throw Object.assign(Error("outside_managed_roots"),{code:"FORBIDDEN"});if(FILE_BLOCKED.some(x=>p===x||p.startsWith(x+path.sep)))throw Object.assign(Error("blocked_path"),{code:"FORBIDDEN"});return p}
function fileRel(p){return p===FILE_HOME?"/home/jorge":p}
function fileStat(p,name){const st=fs.lstatSync(p),mode=(st.mode&0o777).toString(8);return{name,type:st.isDirectory()?"directory":st.isFile()?"file":st.isSymbolicLink()?"symlink":"other",size:st.size,modified:st.mtime.toISOString(),mode,owner:st.uid,group:st.gid,hidden:name.startsWith(".")}}
function fileError(res,e){const c=e?.code;if(c==="FORBIDDEN")return res.status(403).json({error:"forbidden_path"});if(c==="ENOENT"){if(e?.syscall==="spawn zip")return res.status(503).json({error:"zip_not_installed"});if(e?.syscall==="spawn tar")return res.status(503).json({error:"tar_not_installed"});return res.status(404).json({error:"not_found"})}if(c==="EEXIST")return res.status(409).json({error:"already_exists"});if(c==="ENOTEMPTY")return res.status(409).json({error:"directory_not_empty"});res.status(500).json({error:"file_operation_failed"})}
function safeName(v){const n=String(v||"").trim();if(!n||n==="."||n===".."||n.includes("/")||n.includes("\\")||n.length>180)throw Object.assign(Error("invalid_name"),{code:"EINVAL"});return n}
async function copyEntry(src,dst){const st=await fs.promises.lstat(src);if(st.isSymbolicLink())throw Object.assign(Error("symlink_blocked"),{code:"FORBIDDEN"});if(st.isDirectory())return fs.promises.cp(src,dst,{recursive:true,errorOnExist:true,force:false});return fs.promises.copyFile(src,dst,fs.constants.COPYFILE_EXCL)}
function readJsonLines(file,limit=120){try{return fs.readFileSync(file,"utf8").trim().split("\n").filter(Boolean).slice(-limit).map(x=>{try{return JSON.parse(x)}catch{return null}}).filter(Boolean)}catch{return[]}}
