app.get("/api/incidents/v3",async(req,res)=>{try{const [processes,d,nginx,mysql,fail2ban]=await Promise.all([pm2(),disk(),active("nginx"),active("mysql"),active("fail2ban")]),total=os.totalmem(),ram=Math.round((total-os.freemem())/total*100),items=[];const add=(severity,source,title,detail)=>items.push({severity,source,title,detail});if(!nginx)add("critical","nginx","Servidor web fuera de servicio","Nginx no está activo");if(!mysql)add("critical","mysql","Base de datos fuera de servicio","MySQL no está activo");if(!fail2ban)add("warning","security","Protección de acceso inactiva","Fail2Ban no está activo");for(const p of processes)if(p.status!=="online")add("critical","pm2","Proceso "+p.name+" fuera de línea","Estado "+p.status);if(d.percent>=90)add("critical","storage","Espacio en disco crítico",d.percent+"% utilizado");else if(d.percent>=80)add("warning","storage","Espacio en disco elevado",d.percent+"% utilizado");if(ram>=90)add("critical","memory","Memoria crítica",ram+"% utilizada");else if(ram>=80)add("warning","memory","Memoria elevada",ram+"% utilizada");const hist=readJsonLines(METRICS,360),an=metricAnomalies(hist);for(const x of an)add(x.level,"anomaly","Anomalía en "+x.metric.toUpperCase(),"Promedio "+x.current+" vs referencia "+x.baseline);const critical=items.filter(x=>x.severity==="critical").length,warning=items.filter(x=>x.severity==="warning").length;res.set("Cache-Control","no-store").json({state:critical?"critical":warning?"warning":"ok",critical,warning,total:items.length,items,time:new Date().toISOString()})}catch{res.status(500).json({error:"incidents_unavailable"})}});
app.get("/api/diagnostics/v2",async(req,res)=>{const [processes,d,nginx,mysql,fail2ban]=await Promise.all([pm2(),disk(),active("nginx"),active("mysql"),active("fail2ban")]),total=os.totalmem(),memoryPercent=Math.round((total-os.freemem())/total*100),checks=[{name:"Nginx",ok:nginx},{name:"MySQL",ok:mysql},{name:"Fail2Ban",ok:fail2ban},{name:"PM2",ok:processes.every(p=>p.status==="online"),detail:processes.filter(p=>p.status!=="online").map(p=>p.name).join(", ")},{name:"Disco",ok:d.percent<90,detail:d.percent+"%"},{name:"RAM",ok:memoryPercent<90,detail:memoryPercent+"%"}];res.json({checks,healthy:checks.every(x=>x.ok),time:new Date().toISOString()})});
