function cpuUsage(){const cp=os.cpus();let idle=0,total=0;for(const c of cp){idle+=c.times.idle;total+=Object.values(c.times).reduce((a,b)=>a+b,0)}const cur={idle,total};let pct=0;if(cpuPrev){const dt=cur.total-cpuPrev.total,di=cur.idle-cpuPrev.idle;pct=dt>0?Math.max(0,Math.min(100,Math.round((1-di/dt)*100))):0}else{const l=os.loadavg()[0]||0;pct=Math.max(0,Math.min(100,Math.round(l/Math.max(1,cp.length)*100)))}cpuPrev=cur;return pct}
function temperature(){const vals=[];try{for(const z of fs.readdirSync("/sys/class/thermal"))if(z.startsWith("thermal_zone")){try{const v=Number(fs.readFileSync("/sys/class/thermal/"+z+"/temp","utf8").trim())/1000;if(v>0&&v<150)vals.push(v)}catch{}}}catch{}try{for(const h of fs.readdirSync("/sys/class/hwmon")){const dir="/sys/class/hwmon/"+h;for(const f of fs.readdirSync(dir))if(/^temp\d+_input$/.test(f)){try{const v=Number(fs.readFileSync(dir+"/"+f,"utf8").trim())/1000;if(v>0&&v<150)vals.push(v)}catch{}}}}catch{}return vals.length?Math.round(Math.max(...vals)*10)/10:null}
function network(){const ni=os.networkInterfaces();let privateIp=null,iface=null;for(const [n,arr] of Object.entries(ni)){const v=arr?.find(x=>x.family==="IPv4"&&!x.internal);if(v){privateIp=v.address;iface=n;break}}let rx=0,tx=0;if(iface){try{rx=+fs.readFileSync("/sys/class/net/"+iface+"/statistics/rx_bytes","utf8")||0;tx=+fs.readFileSync("/sys/class/net/"+iface+"/statistics/tx_bytes","utf8")||0}catch{}}const now=Date.now(),cur={rx,tx,now},rate=netPrev?{rx:Math.max(0,(rx-netPrev.rx)/((now-netPrev.now)/1000)),tx:Math.max(0,(tx-netPrev.tx)/((now-netPrev.now)/1000))}:{rx:0,tx:0};netPrev=cur;return{interface:iface,privateIp,rxBytes:rx,txBytes:tx,rxPerSec:Math.round(rate.rx),txPerSec:Math.round(rate.tx)}}
async function publicIp(){if(publicIpCache.value&&Date.now()-publicIpCache.at<300000)return publicIpCache.value;const r=await cmd("curl",["-4","-fsS","--max-time","2","https://api.ipify.org"]);if(/^\d{1,3}(\.\d{1,3}){3}$/.test(r))publicIpCache={value:r,at:Date.now()};return publicIpCache.value}
function health(cpu,memory,disk,services,processes,temp){const issues=[];let level="ok";const add=(severity,text)=>{issues.push({severity,text});if(severity==="critical")level="critical";else if(level==="ok")level="warning"};if(cpu>=95)add("critical",`CPU crítica: ${cpu}%`);else if(cpu>=80)add("warning",`CPU elevada: ${cpu}%`);if(memory>=95)add("critical",`RAM crítica: ${memory}%`);else if(memory>=85)add("warning",`RAM elevada: ${memory}%`);if(disk>=95)add("critical",`Disco crítico: ${disk}%`);else if(disk>=85)add("warning",`Disco elevado: ${disk}%`);if(temp!=null&&temp>=90)add("critical",`Temperatura crítica: ${temp}°C`);else if(temp!=null&&temp>=80)add("warning",`Temperatura elevada: ${temp}°C`);for(const [name,on] of Object.entries(services))if(!on)add("critical",`${name} inactivo`);for(const p of processes)if(p.status!=="online")add("critical",`PM2 ${p.name}: ${p.status}`);return{level,issues,summary:level==="ok"?"Todos los servicios y recursos están dentro de parámetros normales":issues[0]?.text||"Revisar servidor"}}
function metricCpuUsage(){const cp=os.cpus();let idle=0,total=0;for(const c of cp){idle+=c.times.idle;total+=Object.values(c.times).reduce((a,b)=>a+b,0)}const cur={idle,total};let pct=0;if(metricCpuPrev){const dt=cur.total-metricCpuPrev.total,di=cur.idle-metricCpuPrev.idle;pct=dt>0?Math.max(0,Math.min(100,Math.round((1-di/dt)*100))):0}metricCpuPrev=cur;return pct}
function metricNetwork(){const ni=os.networkInterfaces();let iface=null;for(const [n,arr] of Object.entries(ni)){if(arr?.some(x=>x.family==="IPv4"&&!x.internal)){iface=n;break}}let rx=0,tx=0;if(iface){try{rx=+fs.readFileSync("/sys/class/net/"+iface+"/statistics/rx_bytes","utf8")||0;tx=+fs.readFileSync("/sys/class/net/"+iface+"/statistics/tx_bytes","utf8")||0}catch{}}const now=Date.now(),cur={rx,tx,now},rate=metricNetPrev?{rx:Math.max(0,(rx-metricNetPrev.rx)/Math.max(.001,(now-metricNetPrev.now)/1000)),tx:Math.max(0,(tx-metricNetPrev.tx)/Math.max(.001,(now-metricNetPrev.now)/1000))}:{rx:0,tx:0};metricNetPrev=cur;return{rxPerSec:Math.round(rate.rx),txPerSec:Math.round(rate.tx)}}
function metricSample(){const total=os.totalmem(),free=os.freemem(),net=metricNetwork();return{time:new Date().toISOString(),cpu:metricCpuUsage(),ram:Math.round((total-free)/total*100),load:Math.round(os.loadavg()[0]*100)/100,rx:net.rxPerSec||0,tx:net.txPerSec||0}}
function storeMetric(){try{append(METRICS,metricSample());const st=fs.statSync(METRICS);if(st.size>2*1024*1024){const lines=fs.readFileSync(METRICS,"utf8").trim().split("\n").slice(-2880);fs.writeFileSync(METRICS,lines.join("\n")+"\n",{mode:0o600})}}catch{}}
const metricTimer=setInterval(storeMetric,60000),metricWarmup=setTimeout(storeMetric,5000);metricTimer.unref?.();metricWarmup.unref?.();
app.get("/api/metrics/v3",(req,res)=>{const n=Number(req.query.limit),raw=Math.min(2880,Math.max(12,Number.isFinite(n)?Math.floor(n):360)),items=readJsonLines(METRICS,raw);res.set("Cache-Control","no-store").json({items,intervalSeconds:60,retention:2880})});
function metricAnomalies(items){if(items.length<30)return[];const recent=items.slice(-10),base=items.slice(-30,-10),avg=(a,k)=>a.length?a.reduce((n,x)=>n+(Number(x[k])||0),0)/a.length:0,an=[];for(const k of ["cpu","ram","load"]){const b=avg(base,k),r=avg(recent,k),delta=r-b,limit=k==="load"?1.5:20;if(delta>=limit)an.push({metric:k,level:delta>=limit*1.75?"critical":"warning",baseline:Math.round(b*10)/10,current:Math.round(r*10)/10,delta:Math.round(delta*10)/10})}return an}
app.get("/api/anomalies/v3",(req,res)=>{const items=readJsonLines(METRICS,360),anomalies=metricAnomalies(items);res.set("Cache-Control","no-store").json({anomalies,enoughData:items.length>=30,samples:items.length,time:new Date().toISOString()})});
app.get("/api/dashboard",async(req,res)=>{const total=os.totalmem(),free=os.freemem(),cpu=cpuUsage(),net=network(),temp=temperature();const [d,processes,nginx,mysql,fail2ban,ddns,ssh,ufw,pub]=await Promise.all([disk(),pm2(),active("nginx"),active("mysql"),active("fail2ban"),active("jr-cloudflare-ddns.timer"),active("ssh"),cmd("ufw",["status"]),publicIp()]);const services={nginx,mysql,fail2ban,ddns,pm2:processes.some(p=>p.status==="online"),ssh,ufw:/status:\s*active/i.test(ufw)},memory={total,used:total-free,free,percent:Math.round((total-free)/total*100)};res.set("Cache-Control","no-store").json({hostname:os.hostname(),platform:os.platform(),release:os.release(),uptime:os.uptime(),load:os.loadavg(),cpuCount:os.cpus().length,cpuPercent:cpu,temperature:temp,network:{...net,publicIp:pub},memory,disk:d,pm2:processes,services,health:health(cpu,memory.percent,d.percent,services,processes,temp),time:new Date().toISOString()})});
